-- Data HPP menu dari file HPP_RUMA_FIX.xlsx (seri Ice / Hot / Can) + harga jual gudang bahan baku



-- harga jual gudang per satuan beli (kemasan) di Matoer; file HPP memakai kemasan berbeda untuk 4 bahan ini
update bahan b set harga_jual_gudang = v.h from (values ('Fresh Milk',300000),('Simple Syrup',12667),
  ('Set Cup Reg (cup, lid, straw)',1400000),('Set Cup Hot (cup, lid, straw)',1300000)) v(n,h)
 where b.nama = v.n and b.mode = 'asli' and b.deleted_at is null;
